import numpy as np
import math
def matrix_elements(X, l, m, n):
	C = np.zeros((16,16))
	C[0,0] = X[0, 0]
	C[0,1] = m*X[0, 2]
	C[0,2] = n*X[0, 2]
	C[0,3] = l*X[0, 2]
	C[0,4] = math.sqrt(3)*l*m*X[0, 6]
	C[0,5] = math.sqrt(3)*m*n*X[0, 6]
	C[0,6] = (1.5*n**2 - 0.5)*X[0, 6]
	C[0,7] = math.sqrt(3)*l*n*X[0, 6]
	C[0,8] = (1/2)*math.sqrt(3)*(-2*m**2 - n**2 + 1)*X[0, 6]
	C[0,9] = (1/4)*math.sqrt(10)*m*(-4*m**2 - 3*n**2 + 3)*X[0, 12]
	C[0,10] = math.sqrt(15)*l*m*n*X[0, 12]
	C[0,11] = (1/4)*math.sqrt(6)*m*(5*n**2 - 1)*X[0, 12]
	C[0,12] = (1/2)*n*(5*n**2 - 3)*X[0, 12]
	C[0,13] = (1/4)*math.sqrt(6)*l*(5*n**2 - 1)*X[0, 12]
	C[0,14] = (1/2)*math.sqrt(15)*n*(-2*m**2 - n**2 + 1)*X[0, 12]
	C[0,15] = (1/4)*math.sqrt(10)*l*(-4*m**2 - n**2 + 1)*X[0, 12]
	C[1,0] = m*X[2, 0]
	C[1,1] = -m**2*X[1, 1] + m**2*X[2, 2] + X[1, 1]
	C[1,2] = m*n*(-X[1, 1] + X[2, 2])
	C[1,3] = l*m*(-X[1, 1] + X[2, 2])
	C[1,4] = l*(-2*m**2*X[1, 5] + math.sqrt(3)*m**2*X[2, 6] + X[1, 5])
	C[1,5] = n*(-2*m**2*X[1, 5] + math.sqrt(3)*m**2*X[2, 6] + X[1, 5])
	C[1,6] = m*(-1.0*math.sqrt(3)*n**2*X[1, 5] + 1.5*n**2*X[2, 6] - 0.5*X[2, 6])
	C[1,7] = l*m*n*(-2*X[1, 5] + math.sqrt(3)*X[2, 6])
	C[1,8] = (1/2)*m*(4*m**2*X[1, 5] - 2*math.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - math.sqrt(3)*n**2*X[2, 6] - 4*X[1, 5] + math.sqrt(3)*X[2, 6])
	C[1,9] = math.sqrt(15)*m**4*X[1, 11] - math.sqrt(10)*m**4*X[2, 12] + (3/4)*math.sqrt(15)*m**2*n**2*X[1, 11] - 3/4*math.sqrt(10)*m**2*n**2*X[2, 12] - 5/4*math.sqrt(15)*m**2*X[1, 11] + (3/4)*math.sqrt(10)*m**2*X[2, 12] - 1/4*math.sqrt(15)*n**2*X[1, 11] + (1/4)*math.sqrt(15)*X[1, 11]
	C[1,10] = (1/2)*l*n*(-3*math.sqrt(10)*m**2*X[1, 11] + 2*math.sqrt(15)*m**2*X[2, 12] + math.sqrt(10)*X[1, 11])
	C[1,11] = -15/4*m**2*n**2*X[1, 11] + (5/4)*math.sqrt(6)*m**2*n**2*X[2, 12] + (1/4)*m**2*X[1, 11] - 1/4*math.sqrt(6)*m**2*X[2, 12] + (5/4)*n**2*X[1, 11] - 1/4*X[1, 11]
	C[1,12] = (1/4)*m*n*(-5*math.sqrt(6)*n**2*X[1, 11] + 10*n**2*X[2, 12] + math.sqrt(6)*X[1, 11] - 6*X[2, 12])
	C[1,13] = (1/4)*l*m*(-15*n**2*X[1, 11] + 5*math.sqrt(6)*n**2*X[2, 12] + X[1, 11] - math.sqrt(6)*X[2, 12])
	C[1,14] = (1/4)*m*n*(6*math.sqrt(10)*m**2*X[1, 11] - 4*math.sqrt(15)*m**2*X[2, 12] + 3*math.sqrt(10)*n**2*X[1, 11] - 2*math.sqrt(15)*n**2*X[2, 12] - 5*math.sqrt(10)*X[1, 11] + 2*math.sqrt(15)*X[2, 12])
	C[1,15] = (1/4)*l*m*(4*math.sqrt(15)*m**2*X[1, 11] - 4*math.sqrt(10)*m**2*X[2, 12] + math.sqrt(15)*n**2*X[1, 11] - math.sqrt(10)*n**2*X[2, 12] - 3*math.sqrt(15)*X[1, 11] + math.sqrt(10)*X[2, 12])
