	C[3,5] = l*m*n*(-2*X[1, 5] + math.sqrt(3)*X[2, 6])
	C[3,6] = l*(-1.0*math.sqrt(3)*n**2*X[1, 5] + 1.5*n**2*X[2, 6] - 0.5*X[2, 6])
	C[3,7] = n*(2*m**2*X[1, 5] - math.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - math.sqrt(3)*n**2*X[2, 6] - X[1, 5] + math.sqrt(3)*X[2, 6])
	C[3,8] = (1/2)*l*(4*m**2*X[1, 5] - 2*math.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - math.sqrt(3)*n**2*X[2, 6] + math.sqrt(3)*X[2, 6])
	C[3,9] = (1/4)*l*m*(4*math.sqrt(15)*m**2*X[1, 11] - 4*math.sqrt(10)*m**2*X[2, 12] + 3*math.sqrt(15)*n**2*X[1, 11] - 3*math.sqrt(10)*n**2*X[2, 12] - math.sqrt(15)*X[1, 11] + 3*math.sqrt(10)*X[2, 12])
