	C[3,14] = (1/4)*l*n*(6*math.sqrt(10)*m**2*X[1, 11] - 4*math.sqrt(15)*m**2*X[2, 12] + 3*math.sqrt(10)*n**2*X[1, 11] - 2*math.sqrt(15)*n**2*X[2, 12] - math.sqrt(10)*X[1, 11] + 2*math.sqrt(15)*X[2, 12])
